// ***************
// Filename: quad_dec_top.sv
// Author: FPGA Cores 4 U
// Description: quad_dec with its AXI4-Lite register interface, the block
//   designs and testbenches instantiate: the register map quad_dec_regs
//   (u_regs, src/include/quad_dec_regs.sv, ID "QDEC", VERSION and DATE at
//   0x00-0x08, the registers from 0x10) and the logic quad_dec (u_core,
//   src/quad_dec.sv), joined by their register ports (cfg_* to the logic,
//   sts_* back). Generated by ip/scripts/regmap_gen.py from
//   quad_dec_regs.json and the ports of quad_dec: regenerate after changing
//   either. Clock - aclk. Reset - synchronous active low aresetn.
// Date: 2026-10-12
module quad_dec_top (
  input  logic        aclk,
  input  logic        aresetn,
  input  logic [7:0]  s_axil_awaddr,
  input  logic        s_axil_awvalid,
  output logic        s_axil_awready,
  input  logic [31:0] s_axil_wdata,
  input  logic [3:0]  s_axil_wstrb,
  input  logic        s_axil_wvalid,
  output logic        s_axil_wready,
  output logic [1:0]  s_axil_bresp,
  output logic        s_axil_bvalid,
  input  logic        s_axil_bready,
  input  logic [7:0]  s_axil_araddr,
  input  logic        s_axil_arvalid,
  output logic        s_axil_arready,
  output logic [31:0] s_axil_rdata,
  output logic [1:0]  s_axil_rresp,
  output logic        s_axil_rvalid,
  input  logic        s_axil_rready,
  input  logic        enc_a_i,
  input  logic        enc_b_i,
  input  logic        enc_z_i,
  output logic [31:0] m_axis_tdata,
  output logic        m_axis_tvalid,
  input  logic        m_axis_tready,
  output logic        m_axis_tlast
);
  // register ports between the register map and the logic
  logic [15:0] cfg_ctrl;
  logic cfg_ctrl_wr;
  logic [31:0] cfg_position;
  logic cfg_position_wr;
  logic [31:0] sts_position;
  logic [31:0] sts_velocity;
  logic [31:0] cfg_window;
  logic [2:0] cfg_status;
  logic cfg_status_wr;
  logic [2:0] sts_status;
  logic [31:0] sts_err_count;
  logic [31:0] sts_index_pos;

  quad_dec_regs u_regs (
    .aclk,
    .aresetn,
    .s_axil_awaddr,
    .s_axil_awvalid,
    .s_axil_awready,
    .s_axil_wdata,
    .s_axil_wstrb,
    .s_axil_wvalid,
    .s_axil_wready,
    .s_axil_bresp,
    .s_axil_bvalid,
    .s_axil_bready,
    .s_axil_araddr,
    .s_axil_arvalid,
    .s_axil_arready,
    .s_axil_rdata,
    .s_axil_rresp,
    .s_axil_rvalid,
    .s_axil_rready,
    .ctrl_o(cfg_ctrl),
    .ctrl_wr_o(cfg_ctrl_wr),
    .position_o(cfg_position),
    .position_wr_o(cfg_position_wr),
    .position_i(sts_position),
    .velocity_i(sts_velocity),
    .window_o(cfg_window),
    .window_wr_o(),
    .status_o(cfg_status),
    .status_wr_o(cfg_status_wr),
    .status_i(sts_status),
    .err_count_i(sts_err_count),
    .index_pos_i(sts_index_pos)
  );
  quad_dec u_core (
    .aclk,
    .aresetn,
    .enc_a_i,
    .enc_b_i,
    .enc_z_i,
    .m_axis_tdata,
    .m_axis_tvalid,
    .m_axis_tready,
    .m_axis_tlast,
    .cfg_ctrl,
    .cfg_ctrl_wr,
    .cfg_position,
    .cfg_position_wr,
    .sts_position,
    .sts_velocity,
    .cfg_window,
    .cfg_status,
    .cfg_status_wr,
    .sts_status,
    .sts_err_count,
    .sts_index_pos
  );
endmodule
